import { describe, it, expect } from "vitest";
import { processScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("Quote - base item premiums", () => {
    it.todo("quotes a sword at base premium plus processing fee for a new customer");
    it.todo("quotes an amulet at its base premium");
    it.todo("quotes a staff at its base premium");
    it.todo("quotes a potion at its base premium");
    it.todo("quotes multiple main items by summing their base premiums");
  });

  describe("Quote - components", () => {
    it.todo("quotes a single rune component at 25 G base premium");
    it.todo("quotes a single moonstone component at 25 G base premium");
    it.todo("quotes three alike components as a building block at 60 G");
    it.todo("quotes four alike components as a block of 3 plus one single");
  });

  describe("Quote - surcharges and discounts", () => {
    it.todo("applies 50% cursed surcharge to a cursed item");
    it.todo("applies 30% high-enchantment surcharge for enchantment level >= 5");
    it.todo("applies 20% loyalty discount for yearsWithMHPCO >= 2");
    it.todo("applies 10% first-insurance surcharge on the first quote");
    it.todo("applies 15% discount on contracts after the first");
    it.todo("rounds the final premium up (in MHPCO's favor) to whole G");
  });

  describe("Claim - payout rules", () => {
    it.todo("subtracts the 100 G deductible from the damage amount");
    it.todo("caps total payout per policy at twice the insurance sum");
    it.todo("reimburses damage to items with enchantment level >= 8 at 50%");
    it.todo("fully reimburses damage to dragon-material items (ignores the 50% enchantment reduction)");
    it.todo("reports remainingCap after a claim");
  });

  describe("CLI/scenario integration", () => {
    it.todo("processes a quote-only scenario and returns a premium result");
    it.todo("processes a quote followed by a claim referencing the policy by index");
  });
});

