export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioOutput {
  results: Result[];
}

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

export const processScenario = (scenario: Scenario): ScenarioOutput => {
  const results: Result[] = scenario.steps.map((step) => {
    if (step.op === "quote") {
      const base = step.items.reduce((s, it) => s + (BASE_PREMIUM[it.type] ?? 0), 0);
      const withFirstInsurance = (base * 110) / 100;
      const premium = Math.ceil(withFirstInsurance - 1e-9) + 5;
      return { premium };
    }
    return { payout: 0, remainingCap: 0 };
  });
  return { results };
};

