const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const basePremiumSum = (items: Item[]): number => {
  const componentCounts: Record<string, number> = {};
  let sum = 0;
  for (const it of items) {
    if (COMPONENT_TYPES.has(it.type)) {
      componentCounts[it.type] = (componentCounts[it.type] ?? 0) + 1;
    } else {
      sum += BASE_PREMIUM[it.type] ?? 0;
    }
  }
  for (const count of Object.values(componentCounts)) {
    const blocks = Math.floor(count / 3);
    const singles = count % 3;
    sum += blocks * 60 + singles * 25;
  }
  return sum;
};

