export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioOutput {
  results: Result[];
}

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const basePremiumSum = (items: Item[]): number => {
  const componentCounts: Record<string, number> = {};
  let sum = 0;
  for (const it of items) {
    if (COMPONENT_TYPES.has(it.type)) {
      componentCounts[it.type] = (componentCounts[it.type] ?? 0) + 1;
    } else {
      sum += BASE_PREMIUM[it.type] ?? 0;
    }
  }
  for (const count of Object.values(componentCounts)) {
    const blocks = Math.floor(count / 3);
    const singles = count % 3;
    sum += blocks * 60 + singles * 25;
  }
  return sum;
};

export const processScenario = (scenario: Scenario): ScenarioOutput => {
  const results: Result[] = scenario.steps.map((step) => {
    if (step.op === "quote") {
      const base = basePremiumSum(step.items);
      const withFirstInsurance = (base * 110) / 100;
      const premium = Math.ceil(withFirstInsurance - 1e-9) + 5;
      return { premium };
    }
    return { payout: 0, remainingCap: 0 };
  });
  return { results };
};

